 вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В Р вЂ№Р В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р В Р вЂ№Р В Р вЂ Р Р†Р вЂљРЎвЂєР РЋРЎвЂє

@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
private fun SetupOptionsContent(
    viewModel: SetupViewModel,
    selectedOption: SetupOption?,
    downloadStates: Map<String, ModelDownloadService.DownloadState>,
    downloadError: String?,
    primaryModelId: String?,
    isDownloading: Boolean
) {
    val downloadState = primaryModelId?.let { downloadStates[it] }

    val progress = when (downloadState) {
        is ModelDownloadService.DownloadState.Downloading -> downloadState.progress
        is ModelDownloadService.DownloadState.Extracting -> -1f
        is ModelDownloadService.DownloadState.Processing -> -1f
        is ModelDownloadService.DownloadState.Success -> 1f
        else -> 0f
    }

    Scaffold(modifier = Modifier.fillMaxSize()) { padding ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = Standards.SpacingXl),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center
        ) {

            // Header section
            AnimatedContent(
                targetState = isDownloading,
                transitionSpec = {
                    (fadeIn(Motion.entrance()) + slideInVertically(
                        initialOffsetY = { -it / 4 },
                        animationSpec = Motion.content()
                    )) togetherWith fadeOut(Motion.exit())
                },
                label = "header"
            ) { downloading ->
                Column(horizontalAlignment = Alignment.CenterHorizontally) {
                    if (downloading) {
                        Text(
                            "\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0430...",
                            style = MaterialTheme.typography.headlineMedium.copy(
                                fontWeight = FontWeight.Bold
                            ),
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Spacer(Modifier.height(Standards.SpacingSm))
                        Text(
                            "\u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043c\u043e\u0436\u043d\u043e \u0441\u0432\u0435\u0440\u043d\u0443\u0442\u044c. \u041a\u043e\u0433\u0434\u0430 \u0432\u0441\u0451 \u0431\u0443\u0434\u0435\u0442 \u0433\u043e\u0442\u043e\u0432\u043e, \u0445\u0430\u0431 \u043f\u0440\u0438\u0448\u043b\u0451\u0442 \u0443\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0435.",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            textAlign = TextAlign.Center
                        )

                        Spacer(Modifier.height(Standards.SpacingXl))

                        // Progress bar with droplets
                        if (progress >= 0f) {
                            Row(
                                modifier = Modifier.fillMaxWidth(),
                                verticalAlignment = Alignment.CenterVertically
                            ) {
                                DropletProgressBar(
                                    progress = progress,
                                    modifier = Modifier.weight(1f).height(40.dp),
                                    barColor = MaterialTheme.colorScheme.primary,
                                    trackColor = MaterialTheme.colorScheme.surfaceContainerHighest
                                )
                                Spacer(Modifier.width(Standards.SpacingMd))
                                Text(
                                    "${(progress * 100).toInt()}%",
                                    style = MaterialTheme.typography.labelMedium.copy(
                                        fontWeight = FontWeight.SemiBold
                                    ),
                                    color = MaterialTheme.colorScheme.onSurfaceVariant
                                )
                            }
                        } else {
                            // Indeterminate for extracting/processing
                            LinearProgressIndicator(
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .height(6.dp)
                                    .clip(RoundedCornerShape(3.dp)),
                                color = MaterialTheme.colorScheme.primary,
                                trackColor = MaterialTheme.colorScheme.surfaceContainerHighest
                            )
                        }
                    } else {
                        Text(
                            "\u041f\u0435\u0440\u0432\u044b\u0439 \u0437\u0430\u043f\u0443\u0441\u043a",
                            style = MaterialTheme.typography.headlineMedium.copy(
                                fontWeight = FontWeight.Bold
                            ),
                            color = MaterialTheme.colorScheme.onSurface
                        )
                        Spacer(Modifier.height(Standards.SpacingSm))
                        Text(
                            "\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0442\u0430\u0440\u0442\u043e\u0432\u044b\u0439 \u0440\u0435\u0436\u0438\u043c. \u0420\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043d\u044b\u0435 uncensored-\u043c\u043e\u0434\u0435\u043b\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b \u0432 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0435 \u043f\u043e\u0441\u043b\u0435 \u0437\u0430\u043f\u0443\u0441\u043a\u0430.",
                            style = MaterialTheme.typography.bodyMedium,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                }
            }

            Spacer(Modifier.height(Standards.SpacingXxl))

            // Options list with staggered animation
            data class SetupCard(
                val option: SetupOption,
                val icon: androidx.compose.ui.graphics.vector.ImageVector,
                val title: String,
                val subtitle: String
            )

            val options = listOf(
                SetupCard(SetupOption.TEXT, TnIcons.Sparkles, "\u0411\u044b\u0441\u0442\u0440\u044b\u0439 \u0447\u0430\u0442", "Ruvltra Claude Code 0.5B \u2022 ~400 MB"),
                SetupCard(SetupOption.TEXT_TTS, TnIcons.Volume, "\u0427\u0430\u0442 + \u043e\u0437\u0432\u0443\u0447\u043a\u0430", "Ruvltra Claude Code 0.5B + Supertonic v2 TTS \u2022 ~663 MB"),
                SetupCard(SetupOption.IMAGE_GEN, TnIcons.Photo, "\u0413\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0439", "AbsoluteReality \u2022 ~1.1 GB"),
                SetupCard(SetupOption.POWER_MODE, TnIcons.Bolt, "\u041d\u0430\u0441\u0442\u0440\u043e\u044e \u043f\u043e\u0437\u0436\u0435", "\u041e\u0442\u043a\u0440\u043e\u044e \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u0438 \u0432\u044b\u0431\u0435\u0440\u0443 \u043c\u043e\u0434\u0435\u043b\u0438 \u0441\u0430\u043c")
            )

            options.forEachIndexed { index, card ->
                key(card.option) {
                    var visible by remember { mutableStateOf(false) }
                    LaunchedEffect(Unit) {
                        delay(index * 80L)
                        visible = true
                    }

                    AnimatedVisibility(
                        visible = visible,
                        enter = fadeIn(Motion.content())
                    ) {
                        SetupOptionCard(
                            icon = card.icon,
                            title = card.title,
                            subtitle = card.subtitle,
                            isSelected = selectedOption == card.option,
                            isDownloading = isDownloading,
                            enabled = selectedOption == null,
                            onClick = { viewModel.selectOption(card.option) }
                        )
                    }

                    if (index < options.lastIndex) {
                        Spacer(Modifier.height(Standards.SpacingSm))
                    }
                }
            }

            // Error message
            AnimatedVisibility(
                visible = downloadError != null,
                enter = Motion.Enter,
                exit = Motion.Exit
            ) {
                Column(
                    modifier = Modifier.padding(top = Standards.SpacingLg),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text(
                        text = downloadError ?: "",
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.error,
                        textAlign = TextAlign.Center
                    )
                    Spacer(Modifier.height(Standards.SpacingSm))
                    TextButton(onClick = { viewModel.retryDownload() }) {
                        Text("Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р Р‹Р РЋРЎСџР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎвЂєР В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р вЂ™Р’ВР В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В°")
                    }
                }
            }

            // Restore from Backup section
            if (!isDownloading) {
                Spacer(Modifier.height(Standards.SpacingXl))
                RestoreFromBackupCard(viewModel = viewModel)
            }
        }
    }
}

