// ==================== Performance Mode Card ====================

@Composable
private fun PerformanceModeCard(
    mode: PerformanceMode,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    description: String,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val backgroundColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.primaryContainer
        else MaterialTheme.colorScheme.surfaceContainerLow,
        animationSpec = Motion.state(),
        label = "perfBg"
    )
    val contentColor by animateColorAsState(
        targetValue = if (isSelected) MaterialTheme.colorScheme.onPrimaryContainer
        else MaterialTheme.colorScheme.onSurface,
        animationSpec = Motion.state(),
        label = "perfContent"
    )

    val label = when (mode) {
        PerformanceMode.PERFORMANCE -> "\u041c\u0430\u043a\u0441\u0438\u043c\u0443\u043c"
        PerformanceMode.BALANCED -> "\u0411\u0430\u043b\u0430\u043d\u0441"
        PerformanceMode.POWER_SAVING -> "\u042d\u043a\u043e\u043d\u043e\u043c\u0438\u044f"
    }

    Surface(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(Standards.RadiusXl),
        color = backgroundColor
    ) {
        Row(
            modifier = Modifier.padding(horizontal = Standards.SpacingLg, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(Standards.SpacingMd)
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = if (isSelected) MaterialTheme.colorScheme.primary else contentColor.copy(alpha = 0.7f),
                modifier = Modifier.size(28.dp)
            )
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = label,
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Medium),
                    color = contentColor
                )
                Text(
                    text = description,
                    style = MaterialTheme.typography.bodySmall,
                    color = contentColor.copy(alpha = 0.7f)
                )
            }
            if (isSelected) {
                Icon(
                    imageVector = TnIcons.RadioButton,
                    contentDescription = "\u0412\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u0440\u0435\u0436\u0438\u043c",
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.size(20.dp)
                )
            }
        }
    }
}

// ==================== Option Card ====================

@Composable
private fun SetupOptionCard(
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    title: String,
    subtitle: String,
    isSelected: Boolean,
    isDownloading: Boolean,
    enabled: Boolean,
    onClick: () -> Unit
) {
    val backgroundColor by animateColorAsState(
        targetValue = when {
            isSelected && isDownloading -> MaterialTheme.colorScheme.primaryContainer
            else -> MaterialTheme.colorScheme.surfaceContainerLow
        },
        animationSpec = Motion.state(),
        label = "optionBg"
    )

    val contentColor by animateColorAsState(
        targetValue = when {
            isSelected && isDownloading -> MaterialTheme.colorScheme.onPrimaryContainer
            !enabled && !isSelected -> MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
            else -> MaterialTheme.colorScheme.onSurface
        },
        animationSpec = Motion.state(),
        label = "optionContent"
    )

    Surface(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(Standards.RadiusXl),
        color = backgroundColor,
        enabled = enabled && !isDownloading
    ) {
        Row(
            modifier = Modifier.padding(horizontal = Standards.SpacingLg, vertical = 14.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(Standards.SpacingMd)
        ) {
            Icon(
                imageVector = icon,
                contentDescription = null,
                tint = if (isSelected && isDownloading) MaterialTheme.colorScheme.primary
                       else contentColor.copy(alpha = 0.7f),
                modifier = Modifier.size(28.dp)
            )
            Column(modifier = Modifier.weight(1f)) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.bodyLarge.copy(fontWeight = FontWeight.Medium),
                    color = contentColor
                )
                Text(
                    text = subtitle,
                    style = MaterialTheme.typography.bodySmall,
                    color = contentColor.copy(alpha = 0.7f)
                )
            }
            if (isSelected && isDownloading) {
                Icon(
                    imageVector = TnIcons.RadioButton,
                    contentDescription = "Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р вЂ Р В РІР‚С™Р РЋРЎС™Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В°Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р Р†Р вЂљРЎС™Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎв„ўР В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В·Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В Р вЂ№Р В Р вЂ Р В РІР‚С™Р РЋРЎС™Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В°",
                    tint = MaterialTheme.colorScheme.primary,
                    modifier = Modifier.size(20.dp)
                )
            }
        }
    }
}

// ==================== Droplet Progress Bar ====================

private data class Droplet(
    val x: Float,
    val startY: Float,
    val speed: Float,
    val radius: Float,
    val alpha: Float,
    var y: Float = startY,
    var life: Float = 1f
)

@Composable
private fun DropletProgressBar(
    progress: Float,
    modifier: Modifier = Modifier,
    barColor: Color,
    trackColor: Color
) {
    val droplets = remember { mutableListOf<Droplet>() }
    var tick by remember { mutableFloatStateOf(0f) }

    LaunchedEffect(Unit) {
        while (true) {
            delay(16L)
            tick += 0.016f
        }
    }

    Canvas(modifier = modifier) {
        val barHeight = 6.dp.toPx()
        val barRadius = barHeight / 2f
        val barY = size.height / 2f - barHeight / 2f
        val filledWidth = size.width * progress.coerceIn(0f, 1f)

