 В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р В РІР‚В Р В Р’В Р Р†Р вЂљРЎв„ўР В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В Р’В Р В РІР‚в„–Р В Р’В Р В Р вЂ№Р В Р Р‹Р Р†РІР‚С›РЎС›Р В Р’В Р вЂ™Р’В Р В РІР‚в„ўР вЂ™Р’В Р В Р’В Р Р†Р вЂљРІвЂћСћР В РІР‚в„ўР вЂ™Р’В Р В Р’В Р вЂ™Р’В Р В Р’В Р Р†Р вЂљР’В Р В Р’В Р вЂ™Р’В Р В Р вЂ Р В РІР‚С™Р РЋРІвЂћСћР В Р’В Р В Р вЂ№Р В Р вЂ Р Р†Р вЂљРЎвЂєР РЋРЎвЂє
        val iterator = droplets.iterator()
        while (iterator.hasNext()) {
            val d = iterator.next()
            d.y += d.speed
            d.life -= 0.025f

            if (d.life <= 0f || d.y > size.height + 10f) {
                iterator.remove()
                continue
            }

            // Droplet shrinks as it falls
            val currentRadius = d.radius * d.life.coerceIn(0f, 1f)
            val currentAlpha = (d.alpha * d.life).coerceIn(0f, 1f)

            drawCircle(
                color = barColor.copy(alpha = currentAlpha),
                radius = currentRadius,
                center = Offset(d.x, d.y)
            )

            // Small highlight on top of droplet
            if (currentRadius > 2f) {
                drawCircle(
                    color = Color.White.copy(alpha = currentAlpha * 0.4f),
                    radius = currentRadius * 0.35f,
                    center = Offset(d.x - currentRadius * 0.2f, d.y - currentRadius * 0.25f)
                )
            }
        }
    }
}
